-- Synthetic users/messages/product snapshots only. Everything rolls back.
begin;
create function pg_temp.ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAILED: %',label;end if;end$$;
create function pg_temp.denied(q text) returns void language plpgsql as $$begin begin execute q;exception when insufficient_privilege or raise_exception or invalid_parameter_value or check_violation then return;end;raise exception 'UNEXPECTEDLY ALLOWED: %',q;end$$;
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data) values
('f1000000-0000-4000-8000-000000000001','buyer@chat.invalid',now(),'{"full_name":"Synthetic Buyer"}'),
('f1000000-0000-4000-8000-000000000002','supplier@chat.invalid',now(),'{}'),
('f1000000-0000-4000-8000-000000000003','unrelated@chat.invalid',now(),'{}'),
('f1000000-0000-4000-8000-000000000004','owner@chat.invalid',now(),'{}'),
('f1000000-0000-4000-8000-000000000005','staff@chat.invalid',now(),'{}'),
('f1000000-0000-4000-8000-000000000006','secondbuyer@chat.invalid',now(),'{}');
update public.user_roles set role=case user_id when 'f1000000-0000-4000-8000-000000000004' then 'super_admin' when 'f1000000-0000-4000-8000-000000000005' then 'admin' else 'supplier' end where user_id in('f1000000-0000-4000-8000-000000000002','f1000000-0000-4000-8000-000000000004','f1000000-0000-4000-8000-000000000005');
insert into public.businesses(id,owner_id,name,division,district) values('f2000000-0000-4000-8000-000000000001','f1000000-0000-4000-8000-000000000002','Synthetic chat business','Dhaka','Dhaka');
insert into public.products(id,business_id,category_id,name,name_bn,description,price,moq,status) values('f3000000-0000-4000-8000-000000000001','f2000000-0000-4000-8000-000000000001',(select id from public.categories limit 1),'Synthetic chat product','Synthetic BN','Synthetic product for chat testing',185,100,'approved'),('f3000000-0000-4000-8000-000000000002','f2000000-0000-4000-8000-000000000001',(select id from public.categories limit 1),'Pending private product','Synthetic BN','Synthetic pending product',200,10,'pending');
create temp table fixture(c uuid,m uuid,access uuid);grant all on fixture to authenticated;
set local request.jwt.claims='{"sub":"f1000000-0000-4000-8000-000000000001","role":"authenticated"}';set local role authenticated;
insert into fixture(c) select (public.chat_start('f2000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000001')->'thread'->>'id')::uuid;
select pg_temp.ok((public.chat_start('f2000000-0000-4000-8000-000000000001')->'thread'->>'id')=(select c::text from fixture),'start reuses buyer-supplier conversation');
select pg_temp.denied($$select public.chat_start('f2000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000002')$$);
update fixture set m=(public.chat_send(c,'Need 500 pieces please','f4000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000001')->>'id')::uuid;
select pg_temp.ok((public.chat_send(c,'Need 500 pieces please','f4000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000001')->>'id')=m::text,'retry reuses same message') from fixture;
select pg_temp.denied(format('select public.chat_send(%L,''Different content'',''f4000000-0000-4000-8000-000000000001'')',c)) from fixture;
select pg_temp.ok((public.chat_messages(c)->'rows'->0->'product_snapshot'->>'price')::numeric=185,'product price snapshot generated by server') from fixture;
select pg_temp.ok(public.chat_unread_total()=0,'outgoing message is not unread for sender');
select pg_temp.denied($$insert into public.conversation_read_states values('00000000-0000-4000-8000-000000000000',auth.uid(),now(),gen_random_uuid(),now())$$);
set local request.jwt.claims='{"sub":"f1000000-0000-4000-8000-000000000002","role":"authenticated"}';
select pg_temp.ok(public.chat_unread_total()=1,'supplier unread count increments');
select pg_temp.ok(public.chat_list('Synthetic Buyer',true)->>'total'='1','supplier searches real buyer name and unread filter');
select public.chat_mark_read(c,m) from fixture;
select pg_temp.ok(public.chat_unread_total()=0,'read cursor clears incoming unread');
select public.chat_send(c,'Yes, available. What sizes?','f4000000-0000-4000-8000-000000000002') from fixture;
select pg_temp.denied(format('select public.chat_mark_read(%L,''00000000-0000-4000-8000-000000000000'')',c)) from fixture;
set local request.jwt.claims='{"sub":"f1000000-0000-4000-8000-000000000001","role":"authenticated"}';
select pg_temp.ok(public.chat_unread_total()=1,'buyer reply unread count');
select pg_temp.ok(public.chat_thread(c)->>'peer_read_id'=m::text,'sender receives actual peer read cursor') from fixture;
select pg_temp.denied(format('select public.chat_messages(%L,null,null,101)',c)) from fixture;
-- Legacy direct inserts also get server-owned product fields and timestamps.
savepoint product_guard;
insert into public.messages(conversation_id,sender_id,body,product_id,product_snapshot,created_at) select c,auth.uid(),'Forged context test','f3000000-0000-4000-8000-000000000001','{"name":"FORGED","account_number":"PRIVATE"}','2099-01-01' from fixture;
select pg_temp.ok((select product_snapshot->>'name'='Synthetic chat product' and not(product_snapshot ? 'account_number') and created_at<now()+interval '1 minute' from public.messages where body='Forged context test'),'forged snapshots and future timestamps replaced');
rollback to product_guard;release product_guard;
reset role;
-- Equal timestamps, more than the old 200-message cap. Trusted fixture writes only.
do $$declare cid uuid;begin select c into cid from fixture;for n in 1..225 loop
 update private.rate_limits set count=0 where user_id='f1000000-0000-4000-8000-000000000001' and scope='messages';
 insert into public.messages(id,conversation_id,sender_id,body,created_at) values(('f5000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,cid,'f1000000-0000-4000-8000-000000000001','Synthetic history '||n,'2026-10-17T00:00:00.123456Z');
end loop;end$$;
create temp table history(data jsonb);grant all on history to authenticated;
set local role authenticated;
insert into history select public.chat_messages(c) from fixture;
do $$declare p jsonb;cid uuid;begin select c into cid from fixture;select data into p from history limit 1;while (p->>'has_more')::boolean loop p=public.chat_messages(cid,p->'oldest');insert into history values(p);end loop;end$$;
select pg_temp.ok((select count(distinct r->>'id')=227 from history cross join lateral jsonb_array_elements(data->'rows') r),'complete history, identical timestamps, no gaps/duplicates beyond 200');
select public.chat_mark_read(c,(public.chat_messages(c)->'newest'->>'id')::uuid) from fixture;
select public.chat_mark_read(c,m) from fixture;
select pg_temp.ok(public.chat_unread_total()=0,'read cursor never moves backwards');
reset role;
update public.account_statuses set status='suspended',reason='Synthetic suspension' where user_id in('f1000000-0000-4000-8000-000000000001','f1000000-0000-4000-8000-000000000002');
set local role authenticated;
select pg_temp.ok(public.chat_start('f2000000-0000-4000-8000-000000000001')->'thread'->>'supplier_status'='suspended','existing conversation retained under suspension');
select public.chat_send(c,'Following up on existing business','f4000000-0000-4000-8000-000000000003') from fixture;
select pg_temp.denied(format('select public.chat_send(%L,''Cannot attach hidden product'',''f4000000-0000-4000-8000-000000000004'',''f3000000-0000-4000-8000-000000000001'')',c)) from fixture;
select pg_temp.ok(public.chat_messages(c)::text like '%Synthetic chat product%','historical product card remains available privately') from fixture;
set local request.jwt.claims='{"sub":"f1000000-0000-4000-8000-000000000006","role":"authenticated"}';
select pg_temp.denied($$select public.chat_start('f2000000-0000-4000-8000-000000000001')$$);
select pg_temp.denied(format('select public.chat_thread(%L)',c)) from fixture;
select pg_temp.denied(format('select public.chat_messages(%L)',c)) from fixture;
select pg_temp.denied(format('select public.chat_send(%L,''Unauthorized message'',''f4000000-0000-4000-8000-000000000005'')',c)) from fixture;
select pg_temp.denied(format('select public.chat_mark_read(%L,%L)',c,m)) from fixture;
select pg_temp.ok(public.chat_list()->>'total'='0' and public.chat_unread_total()=0,'unrelated buyer list/count do not leak');
select pg_temp.ok((select count(*)=0 from public.conversation_read_states),'other participant read cursors private');
set local request.jwt.claims='{"sub":"f1000000-0000-4000-8000-000000000004","role":"authenticated"}';
select pg_temp.denied(format('select public.chat_messages(%L)',c)) from fixture;
update fixture set access=(public.admin_monitor_open(c)->>'access_id')::uuid;
select pg_temp.ok(public.admin_monitor_messages(c,access)::text like '%Synthetic chat product%','audited super admin can review shared product context') from fixture;
select pg_temp.ok((select count(*)=0 from public.messages),'super admin has no broad direct message access');
set local request.jwt.claims='{"sub":"f1000000-0000-4000-8000-000000000005","role":"authenticated"}';
select pg_temp.denied($$select public.chat_list()$$);select pg_temp.denied($$select public.chat_unread_total()$$);
select pg_temp.denied(format('select public.chat_messages(%L)',c)) from fixture;
set local role anon;set local request.jwt.claims='{}';
select pg_temp.ok(not has_function_privilege('anon','public.chat_start(uuid,uuid)','execute') and not has_function_privilege('anon','public.chat_messages(uuid,jsonb,jsonb,integer)','execute'),'anonymous chat RPC execution denied');
reset role;
select 'Marketplace chat authorization/history/read-state checks passed; fixtures rolled back.' result;
rollback;
